import React from 'react';

// Const enum for plugin status (Section 3.7 from source)
export const enum PluginStatus {
  PENDING = 'PENDING',
  ACTIVE = 'ACTIVE',
  ERROR = 'ERROR'
}

// Base event interface for generic event bus
export interface BaseEvent {
  eventType: string;
  timestamp: number;
}

// Component descriptor interface (Section 9.1, 9.4 from source)
